-- Clean any other posts that might have tainted URLs
UPDATE Post 
SET featuredImage = 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1200&q=80'
WHERE featuredImage LIKE '%nucuoimekong%' 
   OR featuredImage LIKE '%nu-cuoi-me-kong%' 
   OR featuredImage LIKE '%ncmk%' 
   OR featuredImage LIKE '%mekong-smile%';
